/**
 * IAP bridge — uses **expo-iap@~3.4.13** (Expo Module, StoreKit 2 on iOS +
 * Google Play Billing on Android).
 *
 * Credit packs are CONSUMABLE products. Product IDs are NOT hardcoded here: they come from
 * the backend (`GET /api/pricing` -> `store_products[].product_id`, e.g. `iema.pack.surge`),
 * which is generated by the pricing engine. The same IDs/prices are exported from
 * Admin > Packs & Pricing for creating the products in Play Console / App Store Connect.
 *
 *  - iOS     -> Apple StoreKit 2   (receipt POST -> /api/payments/iap/apple/verify)
 *  - Android -> Google Play Billing (POST -> /api/payments/iap/google/verify, is_subscription=false)
 *  - Expo Go / web -> module unavailable; caller shows a graceful fallback UI.
 */
import { Platform } from 'react-native';
import Constants from 'expo-constants';
import api from '../api';

// expo-iap still requires native code, so it cannot run inside Expo Go.
const IS_EXPO_GO =
  Constants?.appOwnership === 'expo' ||
  Constants?.executionEnvironment === 'storeClient';

let _iap = null;
let _initialized = false;
let _products = [];
let _purchaseUpdateSub = null;
let _purchaseErrorSub = null;

function loadIap() {
  if (IS_EXPO_GO) return null;
  if (_iap) return _iap;
  try {
    // eslint-disable-next-line global-require
    _iap = require('expo-iap');
    return _iap;
  } catch {
    return null;
  }
}

export function isIapAvailable() {
  return !!loadIap();
}

export async function initIap({ onPurchase, onError } = {}) {
  const iap = loadIap();
  if (!iap) return { ok: false, reason: 'expo-iap unavailable (Expo Go or web)' };
  if (_initialized) return { ok: true, cached: true };
  try {
    await iap.initConnection();
    _purchaseUpdateSub = iap.purchaseUpdatedListener(async (purchase) => {
      try {
        const verified = await verifyPurchase(purchase);
        if (verified?.ok) {
          try {
            // Credit packs are consumable so the user can buy them again.
            await iap.finishTransaction({ purchase, isConsumable: true });
          } catch { /* already finished */ }
          onPurchase?.(verified, purchase);
        } else {
          onError?.(new Error(verified?.error || 'Server rejected receipt'));
        }
      } catch (e) {
        onError?.(e);
      }
    });
    _purchaseErrorSub = iap.purchaseErrorListener((err) => {
      if (err?.code !== 'E_USER_CANCELLED') onError?.(err);
    });
    _initialized = true;
    return { ok: true };
  } catch (e) {
    return { ok: false, reason: e?.message || String(e) };
  }
}

/** Fetch the store's own product records (localized price) for the given SKUs. */
export async function loadProducts(skus) {
  const iap = loadIap();
  if (!iap || !skus?.length) return [];
  try {
    _products = (await iap.fetchProducts({ skus, type: 'in-app' })) || [];
    return _products;
  } catch {
    return [];
  }
}

export async function purchaseProduct(sku) {
  const iap = loadIap();
  if (!iap) throw new Error('In-app purchases are unavailable in Expo Go. Use a native / EAS build.');
  if (!_initialized) await initIap();

  if (Platform.OS === 'android') {
    return iap.requestPurchase({ request: { android: { skus: [sku] } }, type: 'in-app' });
  }
  return iap.requestPurchase({ request: { ios: { sku, quantity: 1 } }, type: 'in-app' });
}

async function verifyPurchase(purchase) {
  if (Platform.OS === 'ios') {
    // Backend validates against Apple's verifyReceipt, which needs the base64 receipt blob.
    const iap = loadIap();
    const receipt = await iap?.getReceiptDataIOS?.();
    if (!receipt) return { ok: false, error: 'no iOS receipt' };
    const { data } = await api.post('/payments/iap/apple/verify', { receipt });
    return data;
  }
  const { data } = await api.post('/payments/iap/google/verify', {
    product_id: purchase.productId,
    purchase_token: purchase.purchaseToken,
    is_subscription: false,
  });
  return data;
}

export async function endIap() {
  const iap = loadIap();
  if (!iap || !_initialized) return;
  try { _purchaseUpdateSub?.remove?.(); } catch { /* ignore */ }
  try { _purchaseErrorSub?.remove?.(); } catch { /* ignore */ }
  try { await iap.endConnection(); } catch { /* ignore */ }
  _initialized = false;
  _purchaseUpdateSub = null;
  _purchaseErrorSub = null;
}
